        ex1title: 'Speckled mug, sage',
        ex1before: 'speckled mug sage glaze 12oz dishwasher ok — small batch, made last week',
        ex1after: 'Hand-thrown Speckled Mug — Sage. Thrown on the wheel in small batches, then glazed in a soft sage that pools a shade deeper near the foot. Iron in the clay burns through as fine speckles, so no two are quite alike.\n\nHolds 12oz. Dishwasher and microwave safe. Made last week, in a batch of eleven.',
        ex2title: 'Linen apron, oat',
        ex2before: 'oat linen apron one size pocket big enough for phone machine wash cold i think?',
        ex2after: 'A linen apron that gets better after the first wash.\n\nCut from 8oz European linen in oat, with a wide neck strap that doesn\'t twist and one pocket deep enough for a phone. One size, with an adjustable waist tie.\n\nMachine wash cold, hang to dry. The wrinkles are part of it.',
        ex3title: 'Brass bookmark',
        ex3before: 'brass bookmark 4 inches cut by hand edges rounded will go dark over time',
        ex3after: 'Solid brass, 4 inches long — heavy enough to stay put, thin enough not to crease the spine.\n\nCut and tumbled by hand, so the edges are rounded rather than sharp. Brass darkens where you hold it. That\'s the material, not a defect, and a soft cloth brings it back.',
        ex4title: 'Kiln day',
        ex4before: 'kiln opening 12 mugs went in 11 survived one cracked handle',
        ex4after: 'Twelve went in. Eleven came out.\n\nThe twelfth cracked at the handle sometime in the last two hours of cooling, which is the part you can\'t watch. I kept it. It\'s on the shelf by the sink, holding pencils.\n\nEleven mugs, sage and oat, in the shop Thursday.',
        ex5title: 'Shelf restock',
        ex5before: 'shelf full again after 3 weeks sorry for the wait',
        ex5after: 'The shelf is full again, three weeks later than I said it would be.\n\nClay arrived late, then the kiln decided to take a week off. Both are fixed. Everything on these two shelves is dry, glazed, and going live at 11am.\n\nThanks for waiting. I know three weeks is a long time in mug terms.',
        ex6title: 'Studio shelf pin',
        ex6before: 'photo of shelf with ceramics morning light',
        ex6after: 'Title: Handmade Ceramic Mugs, Sage Green — Small Batch Pottery\n\nDescription: A shelf of wheel-thrown mugs in sage and oat, drying before the first firing. Handmade stoneware, small batches, glazed and fired in a home studio. Save this for kitchen shelf ideas and handmade pottery inspiration.',
        ex7title: 'Canada shipping',
        ex7before: 'hi do you ship to canada and how much',
        ex7after: 'We do — tracked shipping to Canada is $14, and it usually lands in 6–9 business days once it leaves the studio.\n\nIf you\'d like one held, say the word and I\'ll set it aside for 48 hours.',
        ex8title: 'A three-star review',
        ex8before: '★★★☆☆ — nice mug but smaller than I expected',
        ex8after: 'Fair point, and I should have been clearer — it\'s 12oz, which is a smaller pour than most diner mugs. I\'ve added the height in inches to the listing photos so it\'s easier to judge before ordering.\n\nThanks for taking the time to say so.',
        ex9title: 'Batch 14 dispatch',
        ex9before: '2 mugs to portland tracked should be there thursday packed in paper',
        ex9after: 'Your two mugs left the studio this morning and are tracking for Thursday. They\'re boxed in shredded paper, no plastic.\n\nFirst wash by hand if you can, though the dishwasher won\'t hurt them. If anything arrived unhappy, tell me and I\'ll replace it.',
        ex10title: 'Newsletter blurb',
        ex10before: 'batch 14 ships friday 11 mugs one cracked next batch in a few weeks',
        ex10after: 'Batch fourteen is glazed, fired, and going out Friday. Twelve went into the kiln and eleven came back out — the twelfth cracked at the handle and it\'s holding pencils on my shelf now, which is where the good failures end up. Sage and oat, twelve ounces, $38. There won\'t be a batch fifteen until the clay order lands, so if you\'ve been waiting on one, Friday morning is the time.',
