    faq: {
      eyebrow: 'Hilfe',
      titleA: 'Häufig gestellte',
      titleB: 'Fragen',
      subtitle: 'Alles, was du über Credits, Tarife und Abrechnung wissen musst.',
      q1: 'Was ist Craftly?',
      a1: 'Ein einziger Arbeitsbereich für Marktplatz-Verkäufer, um Listings zu schreiben, Kunden zu antworten, Keywords zu recherchieren, Listings zu übersetzen und zu optimieren, Produkte zu bepreisen und Produktbilder zu generieren — über 10 Marktplätze hinweg, darunter Etsy, Amazon, Shopify, eBay, TikTok Shop, Temu und Walmart.',
      q2: 'Wie funktionieren Credits?',
      a2: 'Jede KI-Generierung (ein Listing, ein Satz Antworten, eine Keyword-Liste usw.) kostet einen Credit. Der kostenlose Tarif enthält 10 Credits pro Monat. Bezahlte Tarife enthalten mehr Credits und schalten zusätzliche Tools wie die Bilderzeugung frei.',
      q3: 'Brauche ich eine Kreditkarte, um zu starten?',
      a3: 'Nein. Der kostenlose Tarif benötigt keine Karte. Registriere dich und lege sofort los.',
      q4: 'Wie kann ich meinen Tarif upgraden oder kündigen?',
      a4: 'Gehe zu Konto → Abrechnung verwalten oder zur Preisseite. Du kannst jederzeit über das Paddle-Kundenportal upgraden, downgraden oder kündigen.',
      q5: 'Welche Tools sind in jedem Tarif enthalten?',
      a5: 'Kostenlos umfasst Listing, Nachrichten, Bewertungen, Social Posts und Keywords. Basic ergänzt Übersetzung, Optimierer und Preisberater. Pro und Scale schalten die Produktbilderzeugung und höhere Monatslimits frei.',
      q6: 'Kann ich diese Tools von Claude Code oder Codex aus nutzen?',
      a6: 'Ja. Das Toolkit enthält einen MCP-Server mit allen Kerntools. Hole dir deinen persönlichen MCP-Schlüssel unter Konto → MCP-Verbindung und füge den etsy-ai-toolkit-mcp-Server zu deinem Client hinzu. Credits und Bildkontingent werden gegen dein eigenes Konto verrechnet.',
      q7: 'Gibt es ein Partnerprogramm?',
      a7: 'Ja. Empfiehl Craftly deinem Publikum und verdiene 30 % jedes bezahlten Tarifs, den du vermittelst (ausgezahlt im ersten Monat). Es gibt einen kostenlosen Tarif zum einfachen Ausprobieren. Siehe die Partner-Seite zum Bewerben.',
      q8: 'Was passiert am Monatsende mit meinen Credits?',
      a8: 'Credits werden zu Beginn jedes Abrechnungsmonats zurückgesetzt. Nicht genutzte Credits werden nicht übertragen.',
      q9: 'Sind meine Daten sicher?',
      a9: 'Ja. Wir verkaufen deine Daten nicht, und Zahlungsdaten werden vollständig von Paddle verarbeitet — wir sehen oder speichern deine Kartennummer nie. Details findest du in unserer Datenschutzerklärung.',
      q10: 'Ist dieses Tool mit Etsy verbunden?',
      a10: 'Nein. Craftly ist ein unabhängiges Produkt und ist nicht mit Etsy, Inc. verbunden oder von ihr unterstützt.',
    },
