        faq1q: 'Wie lege ich meine Stimme fest?',
        faq1a: 'Lege in den Kontoeinstellungen einmal einen Ton und ein paar Schlüsselwörter fest. Jedes Tool liest sie, damit Listings, Posts und Antworten konsistent bleiben.',
        faq2q: 'Kann ich das Sprachprofil von Hand bearbeiten?',
        faq2a: 'Ja — aktualisiere deinen Ton oder deine Schlüsselwörter jederzeit in den Kontoeinstellungen, und alles, was danach generiert wird, verwendet die neuen Einstellungen.',
        faq3q: 'Trainiert ihr auf meinen Listings?',
        faq3a: 'Deine Inhalte gehören dir. Wir nutzen sie, um dir zu dienen, nicht um ein gemeinsames Modell zu verbessern. Lösche etwas und es ist innerhalb von sieben Tagen aus unseren Systemen entfernt.',
        faq4q: 'Was, wenn der Text falsch herauskommt?',
        faq4a: 'Klicke auf Neu generieren, oder passe Ton und Schlüsselwörter in den Kontoeinstellungen an und versuche es erneut. Die Ausgabe gehört immer dir und kann bearbeitet werden.',
