        ex1title: 'Gesprenkelte Tasse, Salbei',
        ex1before: 'gesprenkelte Tasse Salbei Glasur 350 ml spülmaschinenfest ok — kleine Serie, letzte Woche gemacht',
        ex1after: 'Handgedrehte gesprenkelte Tasse — Salbei. In kleinen Serien auf der Scheibe gedreht und in einem weichen Salbeiton glasiert, der am Fuß eine Nuance tiefer verläuft. Eisen im Ton brennt als feine Sprenkel durch, sodass keine zwei ganz gleich sind.\n\nFasst 350 ml. Spülmaschinen- und mikrowellengeeignet. Letzte Woche gemacht, in einer Serie von elf.',
        ex2title: 'Leinenschürze, Hafer',
        ex2before: 'hafer leinen schürze einheitsgröße tasche groß genug für handy maschinenwäsche kalt glaub ich?',
        ex2after: 'Eine Leinenschürze, die nach der ersten Wäsche noch besser wird.\n\nAus 230-g-Leinen aus Europa in Hafer, mit einem breiten Nackenband, das sich nicht verdreht, und einer Tasche, die tief genug für ein Handy ist. Einheitsgröße mit verstellbarem Taillenband.\n\nKalt in der Maschine waschen, hängend trocknen. Die Falten gehören dazu.',
        ex3title: 'Lesezeichen aus Messing',
        ex3before: 'messing lesezeichen 10 cm von hand geschnitten kanten gerundet wird mit der zeit dunkel',
        ex3after: 'Massives Messing, 10 cm lang — schwer genug, um liegen zu bleiben, dünn genug, um den Rücken nicht zu knicken.\n\nVon Hand geschnitten und getrommelt, daher sind die Kanten rund statt scharf. Messing dunkelt dort nach, wo du es hältst. Das ist das Material, kein Mangel, und ein weiches Tuch bringt es zurück.',
        ex4title: 'Brenntag',
        ex4before: 'brennofen öffnung 12 tassen rein 11 überlebt eine henkel gerissen',
        ex4after: 'Zwölf gingen rein. Elf kamen raus.\n\nDie zwölfte riss am Henkel irgendwann in den letzten zwei Stunden der Abkühlung, das ist der Teil, den man nicht sehen kann. Ich habe sie behalten. Sie steht im Regal neben dem Spülbecken und hält Bleistifte.\n\nElf Tassen, Salbei und Hafer, am Donnerstag im Shop.',
        ex5title: 'Regal wieder aufgefüllt',
        ex5before: 'regal nach 3 wochen wieder voll sorry fürs warten',
        ex5after: 'Das Regal ist wieder voll, drei Wochen später als angekündigt.\n\nDer Ton kam zu spät, dann nahm sich der Ofen eine Woche frei. Beides ist behoben. Alles auf diesen zwei Regalen ist trocken, glasiert und geht um 11 Uhr live.\n\nDanke fürs Warten. Ich weiß, drei Wochen sind in Tassen-Zeit eine lange Zeit.',
        ex6title: 'Studio-Regal-Pin',
        ex6before: 'foto vom regal mit keramik morgenlicht',
        ex6after: 'Titel: Handgefertigte Keramiktassen, Salbeigrün — Kleinserien-Keramik\n\nBeschreibung: Ein Regal mit auf der Scheibe gedrehten Tassen in Salbei und Hafer, trocknend vor dem ersten Brand. Handgefertigtes Steinzeug, kleine Serien, glasiert und gebrannt im Heimstudio. Speichere das für Küchenregal-Ideen und Inspiration für handgefertigte Keramik.',
        ex7title: 'Versand nach Kanada',
        ex7before: 'hi verschickst du nach kanada und wie viel',
        ex7after: 'Ja — verfolgter Versand nach Kanada kostet 14 $ und kommt meist in 6–9 Werktagen an, sobald er das Studio verlassen hat.\n\nWenn du eine zurückgelegt haben möchtest, sag Bescheid und ich halte sie 48 Stunden für dich frei.',
        ex8title: 'Eine Drei-Sterne-Bewertung',
        ex8before: '★★★☆☆ — schöne Tasse, aber kleiner als erwartet',
        ex8after: 'Berechtigter Punkt, und ich hätte klarer sein sollen — sie fasst 350 ml, ein kleinerer Guss als die meisten Diner-Tassen. Ich habe die Höhe in Zentimetern zu den Listing-Fotos hinzugefügt, damit es vor der Bestellung leichter einzuschätzen ist.\n\nDanke, dass du dir die Zeit genommen hast, das zu sagen.',
        ex9title: 'Versand von Serie 14',
        ex9before: '2 tassen nach portland verfolgt sollte donnerstag da sein in papier verpackt',
        ex9after: 'Deine zwei Tassen haben das Studio heute Morgen verlassen und sind für Donnerstag verfolgt. Sie sind in geschreddertem Papier verpackt, kein Plastik.\n\nWenn möglich zuerst von Hand waschen, obwohl die Spülmaschine ihnen nicht schadet. Wenn etwas nicht heil ankommt, sag Bescheid und ich ersetze es.',
        ex10title: 'Newsletter-Text',
        ex10before: 'serie 14 verschickt freitag 11 tassen eine gerissen nächste serie in ein paar wochen',
        ex10after: 'Serie vierzehn ist glasiert, gebrannt und geht am Freitag raus. Zwölf gingen in den Ofen und elf kamen zurück — die zwölfte riss am Henkel und hält jetzt Bleistifte in meinem Regal, wo die guten Fehlschläge landen. Salbei und Hafer, 350 ml, 38 $. Eine Serie fünfzehn gibt es erst, wenn die Tonbestellung eintrifft — wer also auf eine wartet, für den ist Freitagmorgen der richtige Zeitpunkt.',
