        sec1h: 'Warum deine ersten 40 Zeichen alles entscheiden',
        sec1p: 'Der Suchalgorithmus von Etsy liest deinen Titel von links. Die Keyword-Phrase in den ersten ~40 Zeichen ist das, worum dein Listing wirklich konkurriert — vergrabe dein Haupt-Keyword bei Position 80 und es ist so gut wie nicht vorhanden. Jeder Titel dieses Generators stellt deine stärkste Long-Tail-Phrase nach vorne, bleibt im 140-Zeichen-Limit von Etsy und kombiniert sie mit 13 Mehrwort-Tags (je max. 20 Zeichen), die dich in gewinnbare Suchpools statt in Ozeane aus Einzelwort-Konkurrenz bringen.',
