        faq2q: 'Was macht einen guten Etsy-Titel aus?',
        faq2a: 'Etsy gewichtet die ersten ~40 Zeichen deines Titels in der Suche am stärksten. Stelle deine stärkste Long-Tail-Keyword-Phrase nach vorne, bleibe unter 140 Zeichen, beschreibe Material und Handwerk und lass Füllwörter wie „schön" oder „toll" weg — Käufer suchen Spezifisches, keine Adjektive.',
