        ex1after: 'Tasse mouchetée tournée à la main — Sauge. Tournée au tour en petites séries, puis émaillée d’un sauge doux qui s’intensifie d’une nuance près du pied. Le fer de l’argile brûle en fines mouchetures, si bien que deux tasses ne sont jamais tout à fait identiques.\n\nContient 340 ml. Passe au lave-vaisselle et au micro-ondes. Faite la semaine dernière, en série de onze.',
