        ex2after: 'Un tablier en lin qui devient encore meilleur après le premier lavage.\n\nCoupé dans du lin européen de 8 oz couleur avoine, avec une large sangle de cou qui ne se tortille pas et une poche assez profonde pour un téléphone. Taille unique, avec une ceinture réglable.\n\nLavage machine à froid, séchage à plat. Les plis font partie du charme.',
