        ex2before: 'delantal lino avena talla única bolsillo lo bastante grande para el móvil lavado a máquina en frío creo?',
        ex2after: 'Un delantal de lino que mejora tras el primer lavado.\n\nCortado de lino europeo de 8 oz en color avena, con una correa de cuello ancha que no se retuerce y un bolsillo lo bastante profundo para un móvil. Talla única, con cintura ajustable.\n\nLavar a máquina en frío, secar colgado. Las arrugas son parte de él.',
