        ex3before: 'marcapáginas latón 10 cm cortado a mano bordes redondeados se oscurecerá con el tiempo',
        ex3after: 'Latón macizo, 10 cm de largo — lo bastante pesado para quedarse quieto, lo bastante fino para no doblar el lomo.\n\nCortado y pulido a mano, así que los bordes son redondeados en lugar de afilados. El latón se oscurece donde lo sostienes. Es el material, no un defecto, y un paño suave lo devuelve.',
