        ex4before: 'apertura de horno 12 tazas entraron 11 sobrevivieron una asa agrietada',
        ex4after: 'Doce entraron. Once salieron.\n\nLa duodécima se agrietó en el asa en algún momento de las dos últimas horas de enfriamiento, la parte que no puedes vigilar. La guardé. Está en la estantería junto al fregadero, sujetando lápices.\n\nOnce tazas, salvia y avena, en la tienda el jueves.',
        ex5title: 'Reposición de estantería',
        ex5before: 'estantería llena otra vez tras 3 semanas perdón por la espera',
        ex5after: 'La estantería está llena de nuevo, tres semanas más tarde de lo que dije.\n\nLa arcilla llegó tarde, y luego el horno decidió tomarse una semana libre. Ambos están arreglados. Todo en estas dos estanterías está seco, esmaltado y sale en directo a las 11 h.\n\nGracias por esperar. Sé que tres semanas es mucho tiempo en términos de tazas.',
        ex6title: 'Pin de estantería de estudio',
