        ex7title: 'Envío a Canadá',
        ex7before: 'hola envías a canadá y cuánto cuesta',
        ex7after: 'Sí — el envío con seguimiento a Canadá cuesta 14 $ y suele llegar en 6–9 días laborables una vez que sale del estudio.\n\nSi quieres que te reserve una, dímelo y la apartaré durante 48 horas.',
        ex8title: 'Una reseña de tres estrellas',
        ex8before: '★★★☆☆ — taza bonita pero más pequeña de lo esperado',
        ex8after: 'Punto justo, y debería haber sido más claro — es de 340 ml, un vertido más pequeño que la mayoría de tazas de cafetería. He añadido la altura en centímetros a las fotos de la ficha para que sea más fácil juzgarlo antes de pedir.\n\nGracias por tomarte el tiempo de decirlo.',
        ex9title: 'Envío del lote 14',
        ex9before: '2 tazas a portland con seguimiento debería llegar el jueves embaladas en papel',
        ex9after: 'Tus dos tazas salieron del estudio esta mañana y tienen seguimiento para el jueves. Van embaladas en papel triturado, sin plástico.\n\nPrimer lavado a mano si puedes, aunque el lavavajillas no les hará daño. Si algo llegara dañado, dímelo y lo reemplazaré.',
        ex10title: 'Extracto de newsletter',
