      subtitle: 'Tutto quello che devi sapere su crediti, piani e fatturazione.',
      q1: "Cos'è Craftly?",
      a1: 'Un unico spazio di lavoro per i venditori dei marketplace: scrivere annunci, rispondere ai clienti, ricercare parole chiave, tradurre e ottimizzare annunci, fissare i prezzi e generare immagini prodotto — su 10 marketplace tra cui Etsy, Amazon, Shopify, eBay, TikTok Shop, Temu e Walmart.',
      q2: 'Come funzionano i crediti?',
      a2: 'Ogni generazione IA (un annuncio, un set di risposte, un elenco di parole chiave, ecc.) costa un credito. Il piano gratuito include 10 crediti al mese. I piani a pagamento includono più crediti e sbloccano strumenti extra come la generazione di immagini.',
