      q5: 'Quali strumenti sono inclusi in ogni piano?',
      a5: 'Gratis include annunci, messaggi, recensioni, post social e parole chiave. Basic aggiunge traduzione, ottimizzatore e consulente prezzi. Pro e Scale sbloccano la generazione di immagini prodotto e limiti mensili più alti.',
