      a6: "Sì. Il toolkit include un server MCP con tutti gli strumenti principali. Prendi la tua chiave MCP personale in Account → Connessione MCP e aggiungi il server etsy-ai-toolkit-mcp al tuo client. Crediti e quota immagini sono conteggiati sul tuo account.",
      q7: 'Avete un programma di affiliazione?',
      a7: "Sì. Consiglia Craftly al tuo pubblico e guadagna il 30 % di ogni piano a pagamento che riferisci (pagato sul primo mese). C'è un piano gratuito per facilitare la prova. Vedi la pagina Affiliati per candidarti.",
      q8: 'Cosa succede ai miei crediti a fine mese?',
