        ex1after: 'Tazza screziata fatta a mano al tornio — Salvia. Tornita al tornio in piccoli lotti, poi smaltata in un salvia morbido che si addensa di una tonalità più profonda vicino al piede. Il ferro nell’argilla brucia in fini screziature, così non ce ne sono due uguali.\n\nContiene 340ml. Lavabile in lavastoviglie e microonde. Fatta la scorsa settimana, in un lotto di undici.',
