        ex2before: 'grembiule lino avena taglia unica tasca abbastanza grande per il telefono lavaggio a freddo in lavatrice penso?',
        ex2after: 'Un grembiule di lino che migliora dopo il primo lavaggio.\n\nTagliato da lino europeo da 8oz color avena, con un’ampia fascia per il collo che non si attorciglia e una tasca abbastanza profonda per un telefono. Taglia unica, con cintura regolabile in vita.\n\nLavaggio in lavatrice a freddo, asciugare appeso. Le pieghe fanno parte di esso.',
