        ex3before: 'segnalibro ottone 10cm tagliato a mano bordi arrotondati si scurirà col tempo',
        ex3after: 'Ottone massiccio, lungo 10cm — abbastanza pesante da restare fermo, abbastanza sottile da non piegare il dorso.\n\nTagliato e rullato a mano, così i bordi sono arrotondati anziché taglienti. L’ottone si scurisce dove lo tieni. È il materiale, non un difetto, e un panno morbido lo riporta.',
