        ex4before: 'apertura forno 12 tazze dentro 11 sopravvissute una manico rotto',
        ex4after: 'Dodici sono entrate. Undici sono uscite.\n\nLa dodicesima si è rotta al manico in un momento delle ultime due ore di raffreddamento, la parte che non puoi sorvegliare. L’ho tenuta. È sullo scaffale vicino al lavandino, tiene le matite.\n\nUndici tazze, salvia e avena, nel negozio giovedì.',
        ex5title: 'Rifornimento scaffale',
        ex5before: 'scaffale di nuovo pieno dopo 3 settimane scusa per l’attesa',
        ex5after: 'Lo scaffale è di nuovo pieno, tre settimane più tardi di quanto avevo detto.\n\nL’argilla è arrivata tardi, poi il forno ha deciso di prendersi una settimana di pausa. Entrambi sono risolti. Tutto su questi due scaffali è asciutto, smaltato e va online alle 11.\n\nGrazie per aver aspettato. So che tre settimane sono tante, in termini di tazze.',
