        ex6before: 'foto di scaffale con ceramica luce del mattino',
        ex6after: 'Titolo: Tazze in ceramica artigianali, verde salvia — Ceramica in piccoli lotti\n\nDescrizione: Uno scaffale di tazze fatte al tornio in salvia e avena, in asciugatura prima della prima cottura. Gres artigianale, piccoli lotti, smaltato e cotto in uno studio casalingo. Salvalo per idee di scaffale da cucina e ispirazione di ceramica artigianale.',
        ex7title: 'Spedizione in Canada',
        ex7before: 'ciao spedite in canada e quanto costa',
        ex7after: 'Sì — la spedizione tracciata in Canada costa 14 $ e di solito arriva in 6–9 giorni lavorativi una volta lasciato lo studio.\n\nSe vuoi che te ne tenga una da parte, dimmelo e la riserverò per 48 ore.',
        ex8title: 'Una recensione a tre stelle',
        ex8before: '★★★☆☆ — bella tazza ma più piccola del previsto',
        ex8after: 'Osservazione giusta, e avrei dovuto essere più chiaro — è da 340ml, una misura più piccola della maggior parte delle tazze da diner. Ho aggiunto l’altezza in centimetri alle foto della scheda per facilitare il giudizio prima dell’ordine.\n\nGrazie per aver dedicato il tempo a dirlo.',
        ex9title: 'Spedizione lotto 14',
        ex9before: '2 tazze a portland tracciate dovrebbe arrivare giovedì imballate in carta',
        ex9after: 'Le tue due tazze hanno lasciato lo studio stamattina e sono tracciate per giovedì. Sono imballate in carta triturata, niente plastica.\n\nPrimo lavaggio a mano se puoi, anche se la lavastoviglie non le danneggia. Se qualcosa arrivasse insoddisfatto, dimmelo e lo sostituirò.',
