        ex10before: 'lotto 14 spedito venerdì 11 tazze una rotta prossimo lotto tra qualche settimana',
        ex10after: 'Il lotto quattordici è smaltato, cotto e parte venerdì. Dodici sono entrate nel forno e undici sono tornate — la dodicesima si è rotta al manico e ora tiene le matite sul mio scaffale, dove finiscono i bei fallimenti. Salvia e avena, 340ml, 38 $. Non ci sarà un lotto quindici finché non arriva l’ordine di argilla, quindi se ne aspettavi una, venerdì mattina è il momento.',
