        ex1after: '핸드 스로우 반점 머그 — 세이지. 소량으로 물레로 빚고 발밑 근처에서 한 톤 더 깊게 고이는 부드러운 세이지 유약을 입혔습니다. 점토 속 철분이 미세한 반점으로 타들어가 두 개가 완전히 같지 않습니다.\n\n340ml 용량. 식기세척기와 전자레인지 사용 가능. 지난주, 11개 로트로 제작.',
