        ex2after: '첫 세탁 후 더 좋아지는 린넨 앞치마.\n\n오트 색상의 8oz 유럽 린넨으로 재단하고, 꼬이지 않는 넓은 목끈과 휴대폰이 들어갈 깊이의 주머니를 갖췄습니다. 프리사이즈, 조절 가능한 허리끈.\n\n냉수 세탁기 세탁, 걸어 건조. 주름은 그 일부입니다.',
