        ex3after: '무쇠 황동, 길이 10cm — 가만히 있을 만큼 무겁고, 책등을 접지 않을 만큼 얇습니다.\n\n손으로 자르고 텀블링하여 모서리가 날카롭지 않고 둥급니다. 황동은 잡는 곳이 어두워집니다. 그것은 결함이 아닌 소재이며, 부드러운 천으로 되돌아옵니다.',
