        ex8title: '3성 리뷰',
        ex8before: '★★★☆☆ — 머그는 예쁘지만 예상보다 작음',
        ex8after: '맞는 지적이고, 더 명확했어야 했습니다 — 340ml로 대부분의 다이너 머그보다 작은 용량입니다. 주문 전 판단하기 쉽도록 리스팅 사진에 센티미터 단위 높이를 추가했습니다.\n\n그렇게 말씀해 주셔서 감사합니다.',
