        ex9before: '포트랜드로 머그 2개 추적 목요일 도착 예정 종이 포장',
        ex9after: '머그 두 개가 오늘 아침 스튜디오를 떠났고 목요일 도착으로 추적됩니다. 분쇄 종이로 포장했으며 플라스틱은 없습니다.\n\n가능하면 처음에는 손세탁하세요. 식기세척기가 해를 끼치지는 않지만. 무언가 불만족스럽게 도착하면 알려주세요. 교환해 드립니다.',
