      subtitle: 'Tudo o que você precisa saber sobre créditos, planos e cobrança.',
      q1: 'O que é a Craftly?',
      a1: 'Um único espaço de trabalho para vendedores de marketplaces escreverem anúncios, responderem clientes, pesquisarem palavras-chave, traduzirem e otimizarem anúncios, definirem preços e gerarem imagens de produto — em 10 marketplaces, incluindo Etsy, Amazon, Shopify, eBay, TikTok Shop, Temu e Walmart.',
      q2: 'Como funcionam os créditos?',
      a2: 'Cada geração de IA (um anúncio, um conjunto de respostas, uma lista de palavras-chave etc.) custa um crédito. O plano grátis inclui 10 créditos por mês. Planos pagos incluem mais créditos e liberam ferramentas extras como geração de imagens.',
      q3: 'Preciso de cartão de crédito para começar?',
      a3: 'Não. O plano grátis não exige cartão. Cadastre-se e comece a gerar agora mesmo.',
      q4: 'Como faço upgrade ou cancelo meu plano?',
      a4: 'Vá em Conta → Gerenciar cobrança, ou na página de Preços. Você pode fazer upgrade, downgrade ou cancelar a qualquer momento pelo portal de clientes Paddle.',
      q5: 'Quais ferramentas estão incluídas em cada plano?',
      a5: 'O Free inclui anúncios, mensagens, avaliações, posts sociais e palavras-chave. O Basic adiciona tradução, otimizador e consultor de preços. Pro e Scale liberam a geração de imagens de produto e limites mensais maiores.',
      q6: 'Posso usar essas ferramentas no Claude Code ou Codex?',
      a6: 'Sim. O toolkit inclui um servidor MCP com todas as ferramentas principais. Pegue sua chave MCP pessoal em Conta → Conexão MCP e adicione o servidor etsy-ai-toolkit-mcp ao seu cliente. Créditos e cota de imagens são contabilizados na sua própria conta.',
      q7: 'Vocês têm um programa de afiliados?',
      a7: 'Sim. Indique a Craftly para sua audiência e ganhe 30% de cada plano pago que indicar (pago no primeiro mês). Há um plano grátis para facilitar o teste. Veja a página de Afiliados para se inscrever.',
      q8: 'O que acontece com meus créditos no fim do mês?',
      a8: 'Os créditos são zerados no início de cada mês de cobrança. Créditos não usados não são transferidos.',
      q9: 'Meus dados estão seguros?',
      a9: 'Sim. Não vendemos seus dados, e os detalhes de pagamento são processados inteiramente pela Paddle — nunca vemos ou armazenamos o número completo do seu cartão. Veja nossa Política de Privacidade.',
      q10: 'Esta ferramenta é afiliada à Etsy?',
      a10: 'Não. A Craftly é um produto independente e não é afiliada nem endossada pela Etsy, Inc.',
