        ex1title: 'Caneca salpicada, sálvia',
        ex1before: 'caneca salpicada esmalte sálvia 12oz lava-louças ok — lote pequeno, feita semana passada',
        ex1after: 'Caneca Salpicada Feita à Mão — Sálvia. Torneada na roda em pequenos lotes, depois esmaltada em um sálvia suave que se acumula um tom mais profundo perto do pé. O ferro na argila queima como finos salpicos, então não há duas iguais.\n\nComporta 12oz. Apta para lava-louças e micro-ondas. Feita semana passada, em um lote de onze.',
        ex2title: 'Avental de linho, aveia',
        ex2before: 'avental de linho aveia tamanho único bolso grande o suficiente para o celular lavagem a frio na máquina acho?',
        ex2after: 'Um avental de linho que fica melhor após a primeira lavagem.\n\nCortado de linho europeu de 8oz em aveia, com uma alça larga de pescoço que não torce e um bolso profundo o suficiente para um celular. Tamanho único, com laço de cintura ajustável.\n\nLavar à máquina com água fria, secar pendurado. As rugas fazem parte.',
        ex3title: 'Marcador de página de latão',
        ex3before: 'marcador de latão 4 polegadas cortado à mão bordas arredondadas vai escurecer com o tempo',
        ex3after: 'Latão maciço, 4 polegadas de comprimento — pesado o suficiente para não se mover, fino o suficiente para não amassar a lombada.\n\nCortado e polido à mão, então as bordas são arredondadas em vez de afiadas. O latão escurece onde você o segura. Isso é o material, não um defeito, e um pano macio o traz de volta.',
        ex4title: 'Dia de forno',
        ex4before: 'abertura do forno 12 canecas entraram 11 sobreviveram uma alça rachada',
        ex4after: 'Doze entraram. Onze saíram.\n\nA décima segunda rachou na alça em algum momento nas últimas duas horas de resfriamento, que é a parte que você não consegue observar. Eu a guardei. Está na prateleira perto da pia, segurando lápis.\n\nOnze canecas, sálvia e aveia, na loja quinta-feira.',
        ex5title: 'Reposição da prateleira',
        ex5before: 'prateleira cheia de novo após 3 semanas desculpe pela espera',
        ex5after: 'A prateleira está cheia de novo, três semanas depois do que eu disse que estaria.\n\nA argila chegou atrasada, depois o forno decidiu tirar uma semana de folga. Ambos estão consertados. Tudo nestas duas prateleiras está seco, esmaltado e entrará no ar às 11h.\n\nObrigado por esperar. Sei que três semanas é muito tempo em termos de caneca.',
        ex6title: 'Prateleira de estúdio pin',
        ex6before: 'foto de prateleira com cerâmicas luz da manhã',
        ex6after: 'Título: Canecas de Cerâmica Artesanais, Verde Sálvia — Cerâmica em Lote Pequeno\n\nDescrição: Uma prateleira de canecas torneadas na roda em sálvia e aveia, secando antes da primeira queima. Grês artesanal, lotes pequenos, esmaltado e queimado em um estúdio caseiro. Salve para ideias de prateleira de cozinha e inspiração em cerâmica artesanal.',
        ex7title: 'Envio para o Canadá',
        ex7before: 'oi vocês enviam para o canadá e quanto custa',
        ex7after: 'Enviamos sim — envio rastreado para o Canadá custa US$ 14, e geralmente chega em 6–9 dias úteis após sair do estúdio.\n\nSe você quiser que eu reserve um, é só avisar e eu separo por 48 horas.',
        ex8title: 'Uma avaliação de três estrelas',
        ex8before: '★★★☆☆ — caneca bonita, mas menor do que eu esperava',
        ex8after: 'Ponto justo, e eu deveria ter sido mais claro — ela tem 12oz, que é um volume menor que a maioria das canecas de lanchonete. Adicionei a altura em polegadas às fotos do anúncio para ficar mais fácil avaliar antes de comprar.\n\nObrigado por tirar um tempo para dizer isso.',
        ex9title: 'Despacho do lote 14',
        ex9before: '2 canecas para portland rastreado deve chegar quinta embaladas em papel',
        ex9after: 'Suas duas canecas saíram do estúdio esta manhã e estão rastreadas para quinta-feira. Elas estão embaladas em papel picado, sem plástico.\n\nLave à mão na primeira vez, se puder, embora a lava-louças não as danifique. Se algo chegar em mau estado, me avise que eu troco.',
        ex10title: 'Trecho de newsletter',
        ex10before: 'lote 14 envia sexta 11 canecas uma rachada próximo lote em algumas semanas',
        ex10after: 'O lote quatorze está esmaltado, queimado e sairá na sexta. Doze entraram no forno e onze voltaram — a décima segunda rachou na alça e agora está segurando lápis na minha prateleira, que é onde as boas falhas acabam. Sálvia e aveia, doze onças, US$ 38. Não haverá lote quinze até o pedido de argila chegar, então se você estava esperando uma, sexta de manhã é a hora.',
